mapper.select:
SELECT p.stock_code AS ticker, p.close_price AS price_krw, p.base_date, p.fetched_at AS price_at, p.source FROM domestic_base_price p JOIN ( SELECT stock_code, MAX(base_date) AS base_date FROM domestic_base_price WHERE stock_code IN
#{ticker}
GROUP BY stock_code ) latest ON latest.stock_code = p.stock_code AND latest.base_date = p.base_date WHERE p.close_price > 0 ORDER BY p.stock_code
